        if (!sheet.allows("reopen", role)) {
            throw new InvalidPeriodException("A " + role + " cannot reopen a period.");
        }
        if (period.isLocked()) {
            throw new InvalidPeriodException("The period is locked.");
        }
        if (!period.isClosed() && !period.isSoftClosed()) {
            throw new InvalidPeriodException("The period is not closed.");
        }
        period.reopen();
        repository.saveAndFlush(period);
    }
}
package net.officefloor.hq.app.period;

import java.util.Comparator;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.AuditUser;
import net.officefloor.hq.app.claim.ClaimLogRepository;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.history.HistoryRecorder;
import net.officefloor.hq.app.person.PersonGradeRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestHeader;

/** Once the sheet's today is changed, with grace days set, closes each open period (not a soft-closed one, whose totals stay as fixed) whose to-date plus the grace
 *  days is before the new today, in order of their to-dates, fixing its totals exactly as a close by hand would (the
 *  permission matrix governs closing by hand, not this), recording each closing with auto=yes, and keeping it in the sheet's history as of its to-date (its end). */
public class AutoClosePeriods {
    public void close(@Val Sheet sheet, PeriodRepository repository, ClaimRepository claims, PersonRepository people,
            RateRepository rates, PersonGradeRepository grades, ClaimLogRepository log, RoleRepository roles,
            @RequestHeader(name = "X-User", required = false) String user, Audit audit,
            HistoryRecorder history) {
        Integer grace = sheet.getGraceDays();
        if (grace == null) {
            return;
        }
        String by = AuditUser.decode(user);
        var due = repository.findBySheetIdOrderByFromDateAscIdAsc(sheet.getId()).stream()
                .filter(p -> !p.isClosed() && !p.isSoftClosed() && p.getToDate().plusDays(grace).isBefore(sheet.getToday()))
                .sorted(Comparator.comparing(Period::getToDate).thenComparing(Period::getId))
                .toList();
        for (Period period : due) {
            ClosePeriod.fix(period, repository, sheet, claims, people, rates, grades, log);
            history.recordOn(period, period.getToDate());
            repository.saveAndFlush(period);
            audit.record("PERIOD_CLOSED sheet=" + sheet.getId() + " by=" + by + " period=" + period.getName()
                    + " total=" + period.getClosedTotal().toPlainString() + " auto=yes");
        }
    }
}
package net.officefloor.hq.app.period;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.MapKeyColumn;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.Map;

/** A sheet's period: a name (unique on the sheet) and a from and to date, inclusive; once closed, its due-total
 *  and each person's (and each person's carried figure) are fixed at what they were on closing, until a steward reopens it. */
@Entity
@Table(name = "period")
public class Period {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(nullable = false)
    private String name;

    @Column(name = "from_date", nullable = false)
    private LocalDate fromDate;

    @Column(name = "to_date", nullable = false)
    private LocalDate toDate;

    /** Whether the period is closed: no claim whose due-by falls in it can be added, edited or change status. */
    @Column(nullable = false)
    private boolean closed;

    /** Whether the period is soft-closed: its figures are fixed as on closing, but claims whose due-by falls in it can still be
     *  added, edited and change status. A period is never both closed and soft-closed. */
    @Column(name = "soft_closed", nullable = false)
    private boolean softClosed;

    /** Whether a steward has locked the period: a locked period cannot be reopened until a steward unlocks it. */
    @Column(nullable = false)
    private boolean locked;

    /** The due-total fixed when the period was closed (or soft-closed); null while it is open. */
    /** The most OPEN or PENDING claims a person may have in the period (by due-by); null for no cap. */
    @Column(name = "open_cap")
    private Integer cap;

    @Column(name = "closed_total", precision = 19, scale = 2)
    private BigDecimal closedTotal;

    /** Each person's due-total fixed when the period was closed, by person id; empty while it is open. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "period_person_total", joinColumns = @JoinColumn(name = "period_id"))
    @MapKeyColumn(name = "person_id")
    @Column(name = "total", precision = 19, scale = 2)
    private Map<Long, BigDecimal> personTotals = new HashMap<>();

    /** Each person's carried figure fixed when the period was closed (or soft-closed), by person id; empty while it is open. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "period_person_carried", joinColumns = @JoinColumn(name = "period_id"))
    @MapKeyColumn(name = "person_id")
    @Column(name = "carried", precision = 19, scale = 2)
    private Map<Long, BigDecimal> personCarried = new HashMap<>();

    /** Each person's opening balance for the period, by person id, added to their carried figure for it; kept while closed
     *  and reopened, though a closed period's fixed carried figures do not change. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "period_person_opening", joinColumns = @JoinColumn(name = "period_id"))
    @MapKeyColumn(name = "person_id")
    @Column(name = "opening", precision = 19, scale = 2)
    private Map<Long, BigDecimal> personOpening = new HashMap<>();

    protected Period() {
    }

    public Period(String sheetId, String name, LocalDate fromDate, LocalDate toDate) {
        this.sheetId = sheetId;
        this.name = name;
        this.fromDate = fromDate;
        this.toDate = toDate;
    }

    public Period(String sheetId, String name, LocalDate fromDate, LocalDate toDate, Integer cap) {
        this(sheetId, name, fromDate, toDate);
        this.cap = cap;
    }

    public Integer getCap() {
        return cap;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public LocalDate getFromDate() {
        return fromDate;
    }

    public LocalDate getToDate() {
        return toDate;
    }

    public boolean isClosed() {
        return closed;
    }

    public boolean isSoftClosed() {
        return softClosed;
    }

    public boolean isLocked() {
        return locked;
    }

    public void setLocked(boolean locked) {
        this.locked = locked;
    }

    public BigDecimal getClosedTotal() {
        return closedTotal;
    }

    public Map<Long, BigDecimal> getPersonTotals() {
        return personTotals;
    }

    public Map<Long, BigDecimal> getPersonCarried() {
        return personCarried;
    }

    public Map<Long, BigDecimal> getPersonOpening() {
        return personOpening;
    }

    /** The person's opening balance for the period: 0.00 for none. */
    public BigDecimal openingOf(Long personId) {
        return personOpening.getOrDefault(personId, BigDecimal.ZERO).setScale(2);
    }

    /** Adds an amount to the person's opening balance for the period. */
    public void addOpening(Long personId, BigDecimal amount) {
        personOpening.merge(personId, amount.setScale(2), BigDecimal::add);
    }

    /** Closes the period, fixing each person's due-total and carried figure for it and its own due-total, their sum. */
    public void close(Map<Long, BigDecimal> personTotals, Map<Long, BigDecimal> personCarried) {
        this.closed = true;
        this.softClosed = false;
        fix(personTotals, personCarried);
    }

    /** Soft-closes the period, fixing each person's due-total and carried figure for it and its own due-total, their
     *  sum, as closing does. */
    public void softClose(Map<Long, BigDecimal> personTotals, Map<Long, BigDecimal> personCarried) {
        this.softClosed = true;
        fix(personTotals, personCarried);
    }

    private void fix(Map<Long, BigDecimal> personTotals, Map<Long, BigDecimal> personCarried) {
        this.personTotals.clear();
        this.personTotals.putAll(personTotals);
        this.personCarried.clear();
        this.personCarried.putAll(personCarried);
        this.closedTotal = personTotals.values().stream().reduce(BigDecimal.ZERO, BigDecimal::add).setScale(2);
    }

    /** Reopens the period, so its due-total and each person's figures for it are live again. */
    public void reopen() {
        this.closed = false;
        this.softClosed = false;
        this.closedTotal = null;
        this.personTotals.clear();
        this.personCarried.clear();
    }

    /** Whether a date falls in this period (inclusive). */
    public boolean contains(LocalDate date) {
        return !date.isBefore(fromDate) && !date.isAfter(toDate);
    }

    /** Whether this period's dates overlap the given ones (both inclusive). */
    public boolean overlaps(LocalDate from, LocalDate to) {
        return !fromDate.isAfter(to) && !from.isAfter(toDate);
    }
}
